import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../App.css";

const Reports = () => {
  const [reports, setReports] = useState([
    {
      id: 1,
      reporter: "JaneFit",
      reason: "Spam listing",
      item: "Suspicious Dumbbell Deal",
    },
    {
      id: 2,
      reporter: "BulkGuy77",
      reason: "Inappropriate language in description",
      item: "Used Bench Press",
    },
  ]);

  const dismissReport = (id) => {
    setReports(reports.filter((r) => r.id !== id));
  };

  return (
    <div>
      <Navbar />
      <main className="favorites-wrapper">
        <h2>User Reports</h2>
        <div className="favorites-grid">
          {reports.map((report) => (
            <div className="favorite-card" key={report.id}>
              <h4>{report.item}</h4>
              <p><strong>Reported by:</strong> {report.reporter}</p>
              <p><strong>Reason:</strong> {report.reason}</p>
              <button className="remove-btn" onClick={() => dismissReport(report.id)}>
                Dismiss Report
              </button>
            </div>
          ))}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Reports;
